def solve_sequence_checked(limit):
    a = [0] * (limit + 1)
    a[1] = 1
    a[2] = 1
    for n in range(3, limit + 1):
        prev_a = a[n-1]
        a[n] = a[prev_a] + a[n - prev_a]
    return a

a_vals = solve_sequence_checked(1024)
for k in range(1, 11):
    n = 2**k
    if n <= 1024:
        print(f"a_{n}: {a_vals[n]}")
